INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杨行密六月启程、七月至广陵", "start_year": 892, "end_year": 892, "time_original": "892年六月丁酉启程；七月丙辰至广陵", "dynasty": "唐", "description": "杨行密六月丁酉率众归扬州，七月丙辰到广陵。", "phases": [], "location_name": "扬州、广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5349e2d1-3c30-55ee-8fc1-d1764b7abde3"}, {"title": "杨行密表田頵守宣州、安仁义守润州", "start_year": 892, "end_year": 892, "time_original": "892年七月丙辰至广陵后条", "dynasty": "唐", "description": "杨行密表请田頵守宣州、安仁义守润州。", "phases": [], "location_name": "宣州、润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cb38a12b-c343-5221-b15f-a3d0630d4139"}, {"title": "扬州富庶与江淮兵火后的对照", "start_year": null, "end_year": null, "time_original": "先是富庶；历次兵火后；确年未载", "dynasty": "唐", "description": "《通鉴》追述扬州曾富庶甲天下，时人称扬一、益二；经历秦、毕、孙、杨兵火后，书中形容江淮东西千里扫地尽矣。", "phases": [], "location_name": "扬州、江淮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "198d45d9-2570-5ef6-befe-236b28da9771"}, {"title": "王建围彭州时诸寨俘掠居民", "start_year": 892, "end_year": 892, "time_original": "围彭州久不下期间；具体日未载", "dynasty": "唐", "description": "王建围彭州久不下，居民逃入山谷。各寨每天外出俘掠，称淘虏；都将先挑选俘获中较好者，其余由士卒分取，成为常例。", "phases": [], "location_name": "彭州、山谷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9155aced-a1a0-5f5c-bd86-52f8ac3bfb33"}, {"title": "王先成劝王宗侃停止俘掠、招安百姓", "start_year": 892, "end_year": 892, "time_original": "围彭州累月期间；具体日未载", "dynasty": "唐", "description": "新津军士王先成本为书生，因世乱为兵。他向王宗侃陈述围军劫财、驱畜、将妇女老弱分作奴婢，致亲属流离、山民饥困；指出久无招安将使民心转向杨晟，又以假设敌军乘寨空袭击说明每日淘虏的军防风险。王宗侃受触动，问如何应对。", "phases": [], "location_name": "彭州、北寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f5026963-e5a3-521a-9f05-fbd841d8484c"}, {"title": "王先成草招安七策，王建悉数实行", "start_year": 892, "end_year": 892, "time_original": "围彭州期间；七策呈报并获采纳", "dynasty": "唐", "description": "王先成经王宗侃命令草拟七条招安措施呈王建：招安山民；禁止淘虏并划樵牧范围；置招安寨派兵巡卫；委王宗侃统一招安；索还俘获居民使家属团聚；置九陇行县以王丕摄令、由居民招亲；使百姓返田卖沤麻以得资粮。王建大喜，立即按所申全部实行。", "phases": [{"title": "招安山民", "description": "招安逃入山中的百姓。"}, {"title": "禁止淘虏、限定樵牧", "description": "禁止各寨军士及子弟擅自外出淘虏，在诸寨旁七里内标界，准许樵牧，越界者斩。"}, {"title": "设寨巡卫", "description": "置招安寨容数千百姓，选谨慎干练将校为招安将，带三十人昼夜持兵巡卫。"}, {"title": "统一招安", "description": "招安须委一人总领，避免各寨自行派军士使百姓惊疑；请将招安事务专交王宗侃。"}, {"title": "归还俘民、团聚亲属", "description": "命四寨及府中诸营索出俘获男女老幼，让父子兄弟夫妇相认相从，登记人数护送招安寨；府营先送回者量给资粮，私匿者斩。"}, {"title": "设行县、居民招亲", "description": "在招安寨置九陇行县，以前南郑令王丕摄县令，设曹局抚理；选居民壮子弟给帖入山招亲，使其知侵掠已禁、被俘者获安堵。"}, {"title": "卖麻资粮、恢复生业", "description": "彭州宜麻，百姓逃山前多有沤藏之麻；令县令晓谕各归田里，取麻出售以得资粮，逐渐复业。"}], "location_name": "彭州、招安寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "591576e8-fa46-5370-b37d-3b3cfd30e2b6"}, {"title": "九陇行县设立，王丕摄县令", "start_year": 892, "end_year": 892, "time_original": "七策获王建采纳时；具体日未载", "dynasty": "唐", "description": "招安七策要求在招安寨设九陇行县，以前南郑令王丕摄县令，设曹局抚理百姓；王建悉按所申实行。", "phases": [], "location_name": "彭州、九陇行县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "20695fd5-2f79-50e5-83a3-ad1681c64158"}, {"title": "招安榜帖后山民出寨、卖麻复业", "start_year": null, "end_year": null, "time_original": "明日榜帖至；三日山民出；月馀寨空", "dynasty": "唐", "description": "招安榜帖次日到，军中不敢犯禁。三日山民竞赴招安寨，容纳不足便扩建，渐成市井并出售麻。居民见村落无抄暴之患，陆续辞县令返回旧业；月余招安寨皆空。", "phases": [], "location_name": "彭州、招安寨、村落", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b197c73-6574-5a75-99fc-ffd26dbd0c1a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

